INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code IN('subcontracts.view','subcontracts.create','subcontracts.edit','subcontracts.change_status','subcontract_boq.view','subcontract_boq.manage','subcontract_boq.approve') WHERE r.code='super_admin' ON DUPLICATE KEY UPDATE role_id=VALUES(role_id);
